-- Agreement v3: live route and time tracking consent, Stripe-hosted ID and tax capture, e-delivery of
-- tax forms, bag-photo confirmation, and snow shoveling. Draft wording for legal review, not final.
-- Users accept the new version before their next job.
UPDATE marketplace_agreements SET is_current = false WHERE is_current AND kind IN ('cleaner', 'customer');

INSERT INTO marketplace_agreements (kind, version, title, body, is_current) VALUES
  ('cleaner', 3, 'Cleaner agreement and liability waiver (draft)',
   E'DRAFT FOR LEGAL REVIEW. Not final wording.\n\n1. Independent contractor. You are not an employee or agent of Frontline. You choose which jobs to take, set your own rates, and decide how to do the work.\n2. Assumption of risk. Cleanup and snow shoveling are physical and can cause injury. You accept those risks and release Frontline from claims for injury or property damage arising from jobs you take, to the extent the law allows.\n3. Safety rules. Do not handle hazardous waste, sharps, biohazards or unknown chemicals. Do not enter confined or unsafe spaces. Do not work alone at night. For snow work, do not use a snow blower or salt spreader unless the job says so, do not work in unsafe weather, and stop if ice or traffic makes the site unsafe. Stop and leave if a site is unsafe.\n4. Your responsibilities. You provide your own tools and protective gear, and you are responsible for your taxes and any local licences.\n5. Conduct. Be honest, respectful and on time. No harassment, theft or off-platform payment.\n6. Age. You confirm you are at least 18.\n7. Payment. The customer pays the posted job price plus a service fee. You receive the full posted price. Payment is held by Frontline when you accept and is sent to your bank through Stripe after the customer confirms the work, or automatically after the review period if there is no dispute. Jobs posted before the service fee change may deduct a platform fee from your price, and the job screen shows which applies.\n8. Cancellations and disputes. If a job is cancelled before work starts, the customer is refunded in full. If there is a dispute, payment stays held while Frontline reviews photos, messages and your job route, and Frontline decides the outcome.\n9. Payout, identity and tax setup. You must finish Stripe payout setup before taking jobs. Stripe collects and verifies your identity and tax details on its own pages. Frontline does not store your ID images or full tax numbers. If you earn enough to require a tax form, such as a 1099, you agree to receive it electronically.\n10. Location and time tracking. While you are working a job in the Frontline mobile app, the app records your location route and the time from arrival to your finished photo. This is required to take jobs. Your route is visible to you and to Frontline reviewers, is recorded only while a job is in progress, and is used to verify the work and resolve disputes. If your route is missing, the job is flagged for review and payment may be delayed.\n11. Photos. You must take a profile photo, and a finished photo of the site that shows all bags you are claiming. You confirm that all bags are in the photo.\n12. Changes. If these terms change you must accept the new version before taking more jobs.',
   true),
  ('customer', 3, 'Customer terms (draft)',
   E'DRAFT FOR LEGAL REVIEW. Not final wording.\n\n1. Authority. You have the right to authorize work on the property you describe.\n2. Accuracy. Describe the site and job honestly and disclose any known hazards.\n3. No hazardous materials. Do not request work involving hazardous waste, sharps, biohazards or anything needing a licence.\n4. Payment and fee. You pay the posted job price plus a service fee. The exact total is shown before you post and on the job. Your card is charged when a cleaner accepts, and the money is held by Frontline. It is released to the cleaner when you confirm the job, or automatically after the review period if there is no dispute.\n5. Cancellations and refunds. You can cancel until work starts and your card is refunded in full. After work starts, open a dispute instead.\n6. Disputes. If you report a problem, payment stays held while Frontline reviews photos, messages and the cleaner''s job route and times, and Frontline decides the outcome.\n7. Bags at your home. If you allow a cleaner to leave bags at your home, you are responsible for providing a safe place for them. This is optional and your address is shared only with the assigned cleaner.\n8. Snow shoveling. Snow jobs cover clearing the area described. Salt or ice treatment is only included if the job says so.\n9. Venue. Frontline is a venue that connects you with independent cleaners and is not the contractor or employer.\n10. Changes. If these terms change you must accept the new version before posting more jobs.',
   true);
